      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize output to prevent XSS (escape HTML entities)
    const sanitizeUser = (user) => ({
      id: Number(user.id), // Ensure it's a number
      name: String(user.name).replace(/[<>]/g, ''), // Basic XSS prevention
      email: String(user.email).replace(/[<>]/g, '')
    });

    res.json(users.map(sanitizeUser));
  }
);

// Example of a parameterized endpoint with validation
app.get('/users/:id',
  [
    param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer')
      .trim().escape(), // Sanitize to prevent XSS
  ],
  validateInput,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    // In real app: fetch from DB with parameterized query
    const users = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com' },
    };

    const user = users[userId];
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

