  // Simple STS endpoint to validate credentials
  const endpoint = `https://sts.amazonaws.com/?Action=GetCallerIdentity&Version=2011-06-15`;

  const req = https.get(endpoint, { headers: { 'Content-Type': 'application/json' } }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      if (res.statusCode === 200) {
        logResult('AWS', true, 'Credentials valid');
      } else {
        logResult('AWS', false, `HTTP ${res.statusCode}`);
      }
    });
  });

  req.on('error', (err) => {
    logResult('AWS', false, err.message);
  });

  req.setTimeout(5000, () => {
    req.destroy();
    logResult('AWS', false, 'Request timed out');
  });
}

