  return new Promise((resolve) => {
    const client = new Client({ connectionString: process.env.DATABASE_URL });

    client.connect()
      .then(() => {
        results.push({ service: 'DATABASE_URL', status: 'SUCCESS', message: 'Connected' });
        return client.end();
      })
      .catch(err => {
        results.push({ service: 'DATABASE_URL', status: 'FAILED', message: err.message });
      })
      .finally(() => resolve());
  });
}

