  return new Promise((resolve) => {
    testFn(key)
      .then(message => results.push({ service: name, status: 'SUCCESS', message }))
      .catch(err => results.push({ service: name, status: 'FAILED', message: err.message }))
      .finally(() => resolve());
  });
}

