  return new Promise((resolve) => {
    // AWS STS GetCallerIdentity - a simple no-cost API call to verify credentials
    const [accessKeyId, secretAccessKey] = [
      process.env.AWS_ACCESS_KEY_ID,
      process.env.AWS_SECRET_ACCESS_KEY
    ];

