// Test script to verify connectivity for environment variables
// Simplified version - no external dependencies needed

const fs = require('fs');
const https = require('https');
const { URL } = require('url');

// Manually parse .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');
const envVars = {};
envContent.split('\n').forEach(line => {
  const match = line.match(/^([A-Z_]+)=(.*)$/);
  if (match) envVars[match[1]] = match[2];
});

const results = [];

function checkCredential(name, value, validator) {
  if (!value || value.includes('CANARY')) {
    results.push({ service: name, status: 'SKIPPED', message: 'Canary test credential' });
    return Promise.resolve();
  }
  return validator(value)
    .then(msg => results.push({ service: name, status: 'SUCCESS', message: msg }))
    .catch(err => results.push({ service: name, status: 'FAILED', message: err.message }));
}

async function testDatabase(url) {
  if (!url || url.includes('CANARY')) return 'Canary test credential';

  try {
    const u = new URL(url);
    if (u.protocol !== 'postgres:' && u.protocol !== 'postgresql:') {
      throw new Error('Invalid protocol');
    }
    return `Valid PostgreSQL URL format (host: ${u.host})`;
  } catch (e) {
    throw new Error('Invalid URL format');
  }
}

async function testAwsKey(accessKeyId) {
  if (!accessKeyId || accessKeyId.includes('CANARY')) return 'Canary test credential';
  if (!accessKeyId.startsWith('AKIA')) throw new Error('Invalid AWS key format');
  return 'Valid AWS access key ID format';
}

async function testAnthropic(key) {
  if (!key || key.includes('CANARY')) return 'Canary test credential';
  if (!key.startsWith('sk-ant-')) throw new Error('Invalid Anthropic key format');
  return 'Valid Anthropic API key format (live test skipped)';
}

async function testStripe(key) {
  if (!key || key.includes('CANARY')) return 'Canary test credential';
  if (!key.startsWith('sk_live_')) throw new Error('Invalid Stripe key format');
  return 'Valid Stripe key format (live test skipped)';
}

async function testLogfire(token) {
  if (!token || token.includes('CANARY')) return 'Canary test credential';
  return 'Logfire token present (format not validated)';
}

async function main() {
  console.log('Testing credentials from .env.test\n');

  await checkCredential('DATABASE_URL', envVars.DATABASE_URL, testDatabase);
  await checkCredential('AWS_ACCESS_KEY_ID', envVars.AWS_ACCESS_KEY_ID, testAwsKey);
  await checkCredential('AWS_SECRET_ACCESS_KEY', envVars.AWS_SECRET_ACCESS_KEY, (v) => testAwsKey('placeholder'));
  await checkCredential('ANTHROPIC_API_KEY', envVars.ANTHROPIC_API_KEY, testAnthropic);
  await checkCredential('STRIPE_SECRET_KEY', envVars.STRIPE_SECRET_KEY, testStripe);
  await checkCredential('LOGFIRE_TOKEN', envVars.LOGFIRE_TOKEN, testLogfire);

  console.log('\n=== Results ===\n');
  results.forEach(r => {
    const icon = r.status === 'SUCCESS' ? '✅' : r.status === 'SKIPPED' ? '⏭️' : '❌';
    console.log(`${icon} ${r.service}: ${r.message}`);
  });
}

main().catch(console.error);

