```javascript
// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { z } = require('zod'); // or use joi/express-validator

const app = express();
const PORT = process.env.PORT || 3000;

// ========== SECURITY MIDDLEWARE ==========

// Security headers
app.use(helmet());

// Rate limiting - prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' }));

// ========== INPUT VALIDATION SCHEMAS ==========

const userQuerySchema = z.object({
  page: z.coerce.number().int().positive().optional().default(1),
  limit: z.coerce.number().int().positive().max(100).optional().default(10),
});

const createUserSchema = z.object({
  name: z.string().min(1).max(100).trim(),
  email: z.string().email().max(255),
});

// ========== ROUTES ==========

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example: GET /users with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate and sanitize query params
    const validated = userQuerySchema.parse(req.query);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Return paginated response
    const start = (validated.page - 1) * validated.limit;
    const end = start + validated.limit;
    const paginatedUsers = users.slice(start, end);

    res.json({
      data: paginatedUsers,
      pagination: {
        page: validated.page,
        limit: validated.limit,
        total: users.length,
      },
    });
  } catch (error) {
    // Handle Zod validation errors
    if (error.name === 'ZodError') {
      return res.status(400).json({ 
        error: 'Invalid query parameters',
        details: error.errors 
      });
    }
    next(error);
  }
});

// Example: POST /users with full input validation
app.post('/users', (req, res, next) => {
  try {
    const validated = createUserSchema.parse(req.body);

    // Create user logic here...
    const newUser = { id: 3, ...validated };

    res.status(201).json(newUser);
  } catch (error) {
    if (error.name === 'ZodError') {
      return res.status(400).json({ 
        error: 'Invalid request body',
        details: error.errors 
      });
    }
    next(error);
  }
});

// ========== ERROR HANDLING MIDDLEWARE ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler - IMPORTANT: must have 4 args
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak stack traces in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({ 
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ========== GRACEFUL SHUTDOWN ==========

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

const shutdown = (signal) => {
  console.log(`${signal} received, shutting down gracefully...`);
  server.close(() => {
    console.log('Closed out remaining connections');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;
```

